import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import jwt from 'jsonwebtoken';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

const JWT_SECRET = process.env.JWT_SECRET || 'dev-fallback-key';

// Middleware: extract user from JWT but don't enforce auth on all routes
function optionalAuth(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (token) {
    try {
      req.user = jwt.verify(token, JWT_SECRET);
    } catch (e) { /* invalid token, proceed unauthenticated */ }
  }
  next();
}

app.use(optionalAuth);

// Search products with filters
app.get('/api/products/search', async (req, res) => {
  const { category, min_price, max_price, sort_by, order } = req.query;

  let baseQuery = 'SELECT id, name, description, price, category, stock_count FROM products WHERE 1=1';
  const params = [];
  let paramIdx = 1;

  if (category) {
    baseQuery += ` AND category = $${paramIdx++}`;
    params.push(category);
  }
  if (min_price) {
    baseQuery += ` AND price >= $${paramIdx++}`;
    params.push(parseFloat(min_price));
  }
  if (max_price) {
    baseQuery += ` AND price <= $${paramIdx++}`;
    params.push(parseFloat(max_price));
  }

  // Dynamic sort - validated against allowed columns
  const allowedSorts = ['price', 'name', 'created_at', 'stock_count'];
  const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
  const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
  baseQuery += ` ORDER BY ${sortCol} ${sortOrder} LIMIT 50`;

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Search failed' });
  }
});

// Get product reviews - VULNERABLE to SQL injection via product_id
app.get('/api/products/:id/reviews', async (req, res) => {
  const productId = req.params.id;
  const { rating_filter, page } = req.query;

  // Developer assumed id is always numeric from frontend routing
  let query = `SELECT r.id, r.body, r.rating, r.created_at, u.username 
               FROM reviews r JOIN users u ON r.user_id = u.id 
               WHERE r.product_id = ${productId}`;

  if (rating_filter && parseInt(rating_filter) >= 1 && parseInt(rating_filter) <= 5) {
    query += ` AND r.rating = ${parseInt(rating_filter)}`;
  }

  const offset = Math.max(0, ((parseInt(page) || 1) - 1) * 20);
  query += ` ORDER BY r.created_at DESC LIMIT 20 OFFSET ${offset}`;

  try {
    const result = await pool.query(query);
    res.json({ reviews: result.rows });
  } catch (err) {
    console.error('Review query error:', err.message);
    res.status(500).json({ error: 'Failed to load reviews' });
  }
});

// Admin endpoint - update product stock (requires admin JWT)
app.put('/api/admin/products/:id/stock', async (req, res) => {
  if (!req.user || req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const { stock_count } = req.body;
  const id = parseInt(req.params.id);
  if (isNaN(id) || typeof stock_count !== 'number') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  await pool.query('UPDATE products SET stock_count = $1 WHERE id = $2', [stock_count, id]);
  res.json({ success: true });
});

// Health check exposing version info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: process.env.APP_VERSION, node: process.version });
});

app.listen(parseInt(process.env.PORT) || 3000);
